require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "while fenced, for an existing company" do
  include_context "timekeeping entry writes"

  # While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen
  it "while fenced refuses writes for an existing company at every generation and changes nothing" do
    Timekeeping::Admission.ensure_initial!
    company = timekeeping_arrange.company
    project = timekeeping_arrange.project(company:)
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    seeded = Timekeeping::EntryWriter.new.call(
      build_entry_command(:update, token:, entry_id:, body: { "note" => "Seeded" }, generation: 1)
    )
    expect(seeded.status).to eq(200)
    baseline = entry_write_counts
    expect(baseline).to include(entries: 1, audit_events: 1, outbox_snapshots: 1, idempotency_receipts: 1, versions: 2)

    Timekeeping::Admission.fence!(lock_timeout: 5)

    [1, 2, nil].each do |generation|
      outcome = Timekeeping::EntryWriter.new.call(
        build_entry_command(:update, token:, entry_id:, body: { "note" => "Fenced #{generation.inspect}" }, generation:)
      )
      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
      expect(entry_write_counts).to eq(baseline)
    end
    expect(Entry.find(entry_id).note).to eq("Seeded")
    # The fence stays in place until a later admission
    expect(Timekeeping::Admission.current.generation).to be_nil
  end
end

