# frozen_string_literal: true
require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "retrying a write refused while fenced" do
  include_context "timekeeping entry writes"

  # A refusal must leave no idempotency receipt; otherwise a retry with the
  # same key after re-admission would replay the stored 409 instead of writing.
  it "a write refused while fenced stores no receipt, so its retry after admit! is written once" do
    Timekeeping::Admission.ensure_initial!
    company = timekeeping_arrange.company
    project = timekeeping_arrange.project(company:)
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 45.0, "note" => "Retried",
             "source" => "manual", "source_metadata" => {} }
    key = SecureRandom.uuid

    Timekeeping::Admission.fence!(lock_timeout: 5)
    refused = Timekeeping::EntryWriter.new.call(build_entry_command(:create, token:, body:, key:, generation: 4))
    expect([refused.status, JSON.parse(refused.body)]).to eq([409, { "reason" => "stale_generation" }])
    expect(IdempotencyReceipt.count).to eq(0)

    Timekeeping::Admission.admit!(generation: 4)
    written = Timekeeping::EntryWriter.new.call(build_entry_command(:create, token:, body:, key:, generation: 4))
    replayed = Timekeeping::EntryWriter.new.call(build_entry_command(:create, token:, body:, key:, generation: 4))

    expect(written.status).to eq(201)
    expect([replayed.status, replayed.body]).to eq([written.status, written.body])
    expect(entry_write_counts.slice(:entries, :audit_events, :outbox_snapshots, :idempotency_receipts))
      .to eq(entries: 1, audit_events: 1, outbox_snapshots: 1, idempotency_receipts: 1)
  end
end

