RSpec.describe Timekeeping::EntryWriter, "with no admission row" do
  include_context "timekeeping entry writes"

  # A write path that created the row at generation 1 would quietly lift a
  # fence whenever the row was lost, so a missing row must refuse instead.
  it "with the admission row missing a write is refused and the row is not created" do
    company = timekeeping_arrange.company
    project = timekeeping_arrange.project(company:)
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    Timekeeping::Admission.delete_all
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 30.0, "note" => "Lost row",
             "source" => "manual", "source_metadata" => {} }
    baseline = entry_write_counts

    outcome = Timekeeping::EntryWriter.new.call(build_entry_command(:create, token:, body:, generation: 1))

    expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
    expect(entry_write_counts).to eq(baseline)
    expect(Timekeeping::Admission.count).to eq(0)
    expect { Timekeeping::Admission.current }.to raise_error(ActiveRecord::RecordNotFound)
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "fence persistence" do
  include_context "timekeeping entry writes"

  # "The fence stays in place until a later admission"
  it "a fence survives refused writes and lifts only when admit! is called again" do
    company = timekeeping_arrange.company
    owner = timekeeping_arrange.user(company:, role: "owner")
    project = timekeeping_arrange.project(company:)
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    token = timekeeping_arrange.token_for(owner)
    stale = { "reason" => "stale_generation" }

    Timekeeping::Admission.fence!(lock_timeout: 5)
    [1, 2, 1].each do |generation|
      outcome = described_class.new.call(build_entry_command(:update, token:, entry_id:, generation:,
                                                                      body: { "note" => "Refused" }))
      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, stale])
      expect(Timekeeping::Admission.current.generation).to be_nil
    end
    expect(Entry.find(entry_id).note).not_to eq("Refused")

    Timekeeping::Admission.admit!(generation: 2)
    admitted = described_class.new.call(build_entry_command(:update, token:, entry_id:, generation: 2,
                                                                     body: { "note" => "Admitted" }))
    expect(admitted.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Admitted")
  end
end

